function doctrineView(world, state, faction, receivedView) {
	const row = world.map.world.rules.ruleSeats.principals.find((r) => r.faction === faction);
	// No row: no doctrine (he answers his commanders and orders nothing of his own; a pack states one for every faction).
	if (row === undefined) return {
		crossNeutral: false,
		concentrateAt: null,
		calls: [],
		offensives: [],
		inquireEveryDays: 0,
		appointKinds: {
			land: [],
			naval: []
		}
	};
	if (state.calendarStart === null) throw new RangeError("the seats layer needs a calendar (a scenario start)");
	const start = daysFromCivil(parseIsoDate(state.calendarStart));
	const sides = receivedDepartmentSides(world, receivedView);
	const due = (date, department) => state.stateDay + 1 >= daysFromCivil(parseIsoDate(date)) - start && sides.get(department) === faction;
	const concentrations = [...row.concentrations ?? []].filter((c) => due(c.fromDate, c.requiresDepartment) && receivedPostSide(world, receivedView, sides, c.post) === faction).sort((a, b) => strictCompare(b.fromDate, a.fromDate) || strictCompare(a.post, b.post));
	const concentration = concentrations[0];
	const transfers = new Map();
	for (const c of concentrations) for (const from of c.fromPosts) if (!transfers.has(from)) transfers.set(from, c.post);
	return {
		crossNeutral: row.crossNeutral,
		concentrateAt: concentration?.post ?? row.concentrateAt,
		...concentration === undefined ? {} : {
			concentrateFrom: concentration.fromPosts,
			concentrateLevies: concentration.receiveLevies ?? true,
			concentrationTransfers: [...transfers].sort(([a], [b]) => strictCompare(a, b)).map(([from, to]) => ({
				from,
				to
			}))
		},
		calls: row.calls.map((c) => ({
			post: c.post,
			regiments: c.regiments,
			termDays: c.termDays,
			day: daysFromCivil(parseIsoDate(c.fromDate)) - start,
			...c.men === undefined ? {} : { men: c.men },
			...c.atPeace === undefined ? {} : { atPeace: c.atPeace },
			...c.arm === undefined ? {} : { arm: c.arm },
			...c.readiness === undefined ? {} : { readiness: c.readiness },
			...c.id === undefined ? {} : {
				id: c.id,
				issued: state.messagesInTransit.some((m) => m.msgOrder !== null && m.msgOrder.orderCall?.callId === c.id && m.msgOrder.orderIssuer === world.faction(faction).principal) || Object.values(state.orderResponses).some((r) => r.respCallId === c.id && r.respPost === c.post)
			}
		})),
		offensives: row.offensives.map((o) => {
			const day = daysFromCivil(parseIsoDate(o.fromDate)) - start;
			if (o.requiresNotice === undefined) return {
				post: o.post,
				objective: o.objective,
				day
			};
			const heard = receivedView.reports.some((r) => r.subjectKind === "situation" && r.subjectId === o.requiresNotice && r.day <= state.stateDay && r.receivedDay <= state.stateDay);
			// The principal remembers his own dispatch, never the addressee's private plan or operation.
			// A later personal order to the same command supersedes this automatic doctrine as well.
			const sent = state.knowledgeBySeat[seatIdFor(world.faction(faction).principal)]?.knownSentOrders ?? [];
			return {
				post: o.post,
				objective: o.objective,
				day,
				ready: heard,
				issued: sent.some((s) => s.sentPost === o.post && s.sentKind === "goal" && s.sentDay >= day)
			};
		}),
		inquireEveryDays: row.inquireEveryDays,
		appointKinds: {
			land: [...row.appointKinds.land],
			naval: [...row.appointKinds.naval]
		}
	};
}

